// Proactive English A2 · Syria Edition · Book 2 · Unit 16 — Answer Key
const L = require('./lib');
const { p, h1, h2, pb, sp, box, table, C } = L;
const out = [];
const S = (t) => p(t, { bold: true, color: C.teal, before: 160, after: 60 });
const A = (t) => p(t, { indent: 200, after: 50 });
const SAMPLE = (paras) => box('Sample answer', paras, 'FFFFFF', C.navy);
const NOTE = (t) => box('Note', [t], C.lyellow, C.orange);

out.push(h1('Unit 16  Then and Now — Answer Key'));
out.push(p('_Proactive English · A2 · Book 2 · Syria Edition · Answer Key_', { color: '7F7F7F' }));
out.push(box('How to use this key', [
  'Every task has an answer or a **full sample**, including brainstorms, free speaking, reports, peer-review slips and homework.',
  '**The spelling rule to mark every single time:** _used to_ keeps its **d** only in the positive. After _didn\'t_ and in questions the **d goes**: _I **used to** go_ · _I **didn\'t use to** go_ · _**Did** you **use to** go?_ They sound identical, so students will not hear the error and nobody but you will correct it.',
  'This unit needs **the photographs**. If students have not brought any, the wall does not happen and five of the seven cycles lose their anchor. Ask again at the start of 16.1 and lend your own if you have to.',
], C.lblue, C.navy));

// ===================== 16.1 =====================
out.push(pb());
out.push(h2('16.1  I used to walk to school'));
out.push(S('Stage 1 · Get ready'));
out.push(A('**a** Open. Typical: _I used to walk everywhere · I used to watch television with my family · I used to live with four people · I used to have time on a Friday._ Write five and underline _used to_ in each.'));
out.push(A('**b** Open — true or false for each student. The point is the **form**, not the answer, so make them say the whole sentence: _No, I **didn\'t use to** walk to school._'));
out.push(S('Stage 2 · Listen and read'));
out.push(A('**a** **B** – photographs from at least ten years ago.'));
out.push(A('**b** **1** He used to walk up to the Citadel with his uncle\'s camera and take exactly four photographs.   **2** Her grandmother\'s kitchen — she used to think it was boring and hot and full of women telling her what to do.'));
out.push(S('Language box · Practise'));
out.push(A('**1** I **used to walk** to school every day.   **2** She **didn\'t use to like** coffee.   **3** **Did** you **use to live** in Aleppo?   **4** We **used to stop** halfway for tea.   **5** He **didn\'t use to have** a telephone.   **6** They **used to be** neighbours of ours.'));
out.push(NOTE('Items 2, 3 and 5 are the **d**. Items 1, 4 and 6 keep it. Put the six answers on the board in two columns — _with d_ and _without d_ — and the rule needs no explaining at all.'));
out.push(S('Stage 3 · Practise (sample – Card A, when you were fourteen)'));
out.push(SAMPLE([
  '**A:** Tell me about when you were fourteen.',
  '**B:** I used to walk to school with my cousin every morning.',
  '**A:** Every?',
  '**B:** Every. And I used to play football in the street until it was dark, and I used to read the same four books again and again because they were the four we had.',
  '**A:** And now?',
  '**B:** Now I read on a screen and I finish nothing.',
  '**A:** Was there anything you didn\'t use to like?',
  '**B:** I didn\'t use to like Fridays. Everybody was at home and there was nowhere in the flat to be alone.',
]));
out.push(S('Stage 3R · Perform – listener task (sample)'));
out.push(A('_I used to walk to school · I used to play football in the street · I used to read the same four books_ — and _I **didn\'t use to** like Fridays_. Spelling check: three with the **d**, one without.'));
out.push(S('Stage 4 · Your turn (sample)'));
out.push(SAMPLE([
  '_This is our flat in Latakia, in 2012. I was eleven. Every summer we used to come here for six weeks, and we used to eat on that balcony every single evening because the kitchen was too hot to be in. I used to sleep on the floor in the room at the back with my two cousins. I didn\'t use to like going home._',
  '**Partner:** _What is the bicycle in the corner?_ — **B:** _…That was my uncle\'s. I have not thought about that bicycle for fifteen years._',
]));
out.push(S('Stage 4R · Report (sample)'));
out.push(SAMPLE(['Rami\'s photograph is the road to Homs, which he said was not interesting and which turned out to be the best one in the room. His family used to drive it every month, and they used to stop halfway at a tea place, every single time, because his father used to say you cannot arrive without stopping. He didn\'t use to pay any attention to the place at all. It is in the corner of the photograph by accident, and it isn\'t there any more, and that corner is now the only picture of it that he has.']));
out.push(S('Board clinic – typical mistakes'));
out.push(A('✗ I didn\'t used to like it. → ✓ I **didn\'t use to** like it.   ✗ I used to went there. → ✓ I used to **go** there.   ✗ I used to go there last year. → ✓ I **went** there last year.   ✗ I am used to walk to school. → ✓ I **used to walk** to school.'));
out.push(S('Stage 5 · Read'));
out.push(A('**1** Because four photographs was all the film he could afford to buy.'));
out.push(A('**2** She used to make bread on that table every morning of her life.'));
out.push(A('**3** The tea place his family always stopped at is in the corner of it by accident — and it is now the only picture of that place that exists.'));
out.push(S('Stage 6 · Write with help (sample)'));
out.push(SAMPLE([
  '**Lina · my grandfather\'s shop, Jaramana, 2011.**',
  'I was seventeen.',
  'Every Saturday I used to work here from eight until two.',
  'I used to weigh everything by hand and I used to write the prices on a board with chalk.',
  'I didn\'t use to understand why he knew every customer\'s name.',
  'The shop is now a telephone shop, and the board is in my mother\'s kitchen.',
]));
out.push(S('Stage 7 · Write freely (sample, 128 words)'));
out.push(SAMPLE([
  '**2014**',
  'Every Thursday that year I used to take the six o\'clock bus to Homs and come back on the Saturday. Forty-one weeks out of fifty-two. I used to do my reading on the bus, and I used to know which seat was over the wheel and avoid it.',
  'I didn\'t use to mind the journey. What I didn\'t use to like was Sunday morning, when it was over and the week started again.',
  'I used to think that year was temporary and that the real part of my life was waiting somewhere after it.',
  'What I know now is that it was not temporary and it was not waiting. It was just my life, going past at seventy kilometres an hour with a book on my knee.',
]));
out.push(S('Stage 7P · Respond (sample slip)'));
out.push(A('★ _"forty-one weeks out of fifty-two" — I can see the whole year in that number._   ✓ _"I used to do my reading" needs a frequency — every journey? both ways?_   ? _What happened at the end of the year?_'));
out.push(S('Stage 7R · Share'));
out.push(A('The wall is now the room. Leave it up for the whole of Unit 16 — five of the seven cycles refer back to it, and 16.7 is about explaining exactly this kind of caption to somebody who cannot read it.'));
out.push(S('Homework (sample – the parent\'s caption)'));
out.push(SAMPLE(['**The road to Homs, 2012 — Abu Rami.** I was fifty-eight. We used to drive this road once a month to see my mother, and I used to stop at the tea place halfway, every time, because my father stopped there with me and because arriving tired is not arriving. I didn\'t use to say why. The boy used to sit in the back and read and complain about the stopping, and I used to let him complain. I did not know he was looking out of the window at all.']));

// ===================== 16.2 =====================
out.push(pb());
out.push(h2('16.2  Did you use to play in the street?'));
out.push(S('Stage 1 · Get ready'));
out.push(A('**a** Open. Eight in ninety seconds. Typical: _Did you use to walk to school? · Did you use to have a television? · Did you use to play in the street? · Did you use to go away in the summer?_'));
out.push(A('**b** **1** _Did you **use to** play?_   **2** _**Did** you **use to** live here?_ (there is no present form)   **3** _Did you use to **like** it?_   **4** _**Did** you **use to walk** to school?_'));
out.push(S('Stage 2 · Listen and read'));
out.push(A('**a** **A** – Lama, for her class.'));
out.push(A('**b** **1** Nine, in four hundred metres. There are now two, and one is really a stationery shop with a shelf.   **2** They used to walk slowly along the street looking in windows, without being in a hurry, and some of them used to buy a book.'));
out.push(S('Language box · Practise'));
out.push(A('**1** **Did you use to play** in the street?   **2** **Did there use to be** a cinema here?   **3** **What did you use to do** in the summer?   **4** **Did your father use to work** here?   **5** **Did people use to buy** more books?'));
out.push(NOTE('Item 2 is the one to drill until it is automatic — _**Did there use to be**…?_ is four small words that students assemble wrongly in about six different ways. Ask it round the class about six different things before you move on.'));
out.push(S('Stage 3 · Practise (sample – Card A, the shopkeeper)'));
out.push(SAMPLE([
  '**A:** Can I ask you about this street?',
  '**B:** Ask.',
  '**A:** Did you use to work here when you were young?',
  '**B:** I did. I used to sit behind the counter and watch the door.',
  '**A:** Did there use to be other shops like yours?',
  '**B:** There used to be nine. Now there are two.',
  '**A:** What did you use to do on a Thursday evening?',
  '**B:** Nothing. I used to stand at the door, because the whole street was full of people walking slowly.',
  '**A:** Did people use to buy more?',
  '**B:** No — and everybody expects me to say yes. They used to buy the same amount. They used to come in more.',
]));
out.push(S('Stage 3R · Perform – listener task (sample)'));
out.push(A('_nine → two · four hundred metres · thirty years_ — and the thing that surprised the interviewer was that people did **not** use to buy more.'));
out.push(S('Stage 4 · Your turn (sample)'));
out.push(SAMPLE([
  '**A:** Did you use to play in the street? — **B:** Until my mother shouted from the window. **A:** Did there use to be cars parked in it? — **B:** Not one. That is why we could play. **A:** What did you use to do in the summer? — **B:** Nothing. We didn\'t use to go anywhere at all. **A:** Did you use to like being the oldest? — **B:** No. The oldest is responsible for everybody and gets nothing for it.',
  '**b** _The question nobody has ever asked me: what did your street smell like?_',
]));
out.push(S('Stage 4R · Report (sample)'));
out.push(SAMPLE(['Nour used to live on the ground floor of a building with no lift and twenty-two children in it. She used to play in the street until her mother shouted from the window, and she says there didn\'t use to be a single car parked in it, which is why they could play there at all. They didn\'t use to go anywhere in the summer. She says the thing she didn\'t use to like was being the oldest, because the oldest one is responsible for all the others and gets nothing for it. The question nobody has ever asked her is what her street smelled like.']));
out.push(S('Board clinic – typical mistakes'));
out.push(A('✗ Did you used to play? → ✓ Did you **use to** play?   ✗ Did you use to played? → ✓ Did you use to **play**?   ✗ Do you use to live here? → ✓ **Do** you **live** here?   ✗ Did there used to be a cinema? → ✓ **Did there use to be** a cinema?'));
out.push(S('Stage 5 · Read'));
out.push(A('**1** On a box behind the counter, watching the door.'));
out.push(A('**2** That the shops were closing. Nobody noticed any single one of them closing; people only noticed when there were three left.'));
out.push(A('**3** Not the number of books people buy — that is the same. What has changed is that people no longer **come in** without a reason, and a bookshop lives on that kind of customer.'));
out.push(S('Stage 6 · Write with help (sample)'));
out.push(SAMPLE([
  '**FORTY-FIVE IN A CLASS** — an interview with Mr Nabil, 64, retired teacher, Mezzeh',
  'I asked Mr Nabil six questions about the school he taught in for thirty-five years.',
  '**Did you use to have bigger classes?** He says there used to be forty-five children in a class and that there are now thirty.',
  '**Did there use to be a library?** There didn\'t use to be one at all. Now there is one, and he says almost nobody uses it.',
  '**What has changed most?** He says parents. Parents didn\'t use to come to the school at all except when something was wrong.',
  'The sentence I keep thinking about: "We had more children and fewer problems, and I have never been able to explain that to anybody, including myself."',
]));
out.push(S('Stage 7 · Write freely (sample, 143 words)'));
out.push(SAMPLE([
  '**THE BUILDING WITH TWENTY-TWO CHILDREN IN IT** — an interview with my mother, 58, Mezzeh',
  'I asked my mother six questions. She said nobody has ever asked her any of them.',
  '**Did you use to know everybody in the building?** She says there used to be twenty-two children in it and that she knew every one of their mothers by name. She says she now knows two.',
  '**Did there use to be a caretaker?** There used to be one who lived in the ground-floor flat. There didn\'t use to be a lock on the main door, because there didn\'t need to be.',
  '**Did people use to visit?** Constantly, and without ringing. She says her mother used to cook as if four extra people were coming, every day, and that four extra people usually came.',
  '**What did you use to worry about?** She says money, exactly the same as now, and that this is the only thing that has not changed in forty years.',
  'Her words: "The building is quieter and I am not sure that is the same as better."',
]));
out.push(S('Stage 7P · Respond (sample slip)'));
out.push(A('★ _"she now knows two" — the whole interview is in that number._   ✓ _The caretaker question has no answer about now — is there one?_   ? _What did you want to ask and didn\'t?_'));
out.push(S('Stage 7R · Share'));
out.push(A('Reading the last sentences alone is quick and it proves the Writer\'s box: a quotation that carries the person in it is guessable, and a tidied-up one is not. The ones the class cannot place are the ones the student improved.'));
out.push(S('Homework (sample – six questions for the oldest person you know)'));
out.push(SAMPLE(['**For my grandfather, 88.** 1 Did you use to know the name of everybody on your street? 2 What did you use to do on a Friday? 3 Did there use to be a doctor near the house? 4 What did you use to eat that nobody eats now? 5 Did you use to think you would live here all your life? 6 What has stopped that you miss, and what has stopped that you don\'t? **The two I have never asked anybody:** number 5, and the second half of number 6.']));

// ===================== 16.3 =====================
out.push(pb());
out.push(h2('16.3  There used to be a cinema here'));
out.push(S('Stage 1 · Get ready'));
out.push(A('**a** Open. Insist on the two _there didn\'t use to be_ sentences — students produce the positive easily and avoid the negative, which is where the **d** error lives.'));
out.push(A('**b** **1** _There **used to be** a cinema here for forty years._ (a long state, now ended)   **2** _There **was** a very good film on last night._ (one occasion — _used to_ is impossible)   **3** _There **used to be** three bakeries._'));
out.push(S('Stage 2 · Listen and read'));
out.push(A('**a** **B** – two photographs of the same corner, 2011 and last month.'));
out.push(A('**b** **1** A cinema — it closed in about 2008, was a shop for six years, and then became a bank.   **2** A pavement on that side. There was none at all; people used to walk in the road.'));
out.push(S('Language box · Practise'));
out.push(A('**1** **There used to be** a cinema on this corner until 2008.   **2** **There was** a very good concert last Friday.   **3** **There didn\'t use to be** any shops on this side at all.   **4** **There used to be** three bakeries and now there is one.   **5** **There didn\'t use to be** a pavement here, which is why people walked in the road.'));
out.push(S('Stage 3 · Practise (sample – Card A, your corner)'));
out.push(SAMPLE([
  '**A:** This is our corner, about ten years ago.',
  '**B:** What was here?',
  '**A:** There used to be a cinema, where the bank is now.',
  '**B:** And this?',
  '**A:** There didn\'t use to be a pavement on that side at all. People used to walk in the road.',
  '**B:** So what has got better?',
  '**A:** The pavement, the pharmacy, and six buses an hour instead of one.',
  '**B:** And what has got worse?',
  '**A:** The trees. There used to be four. There is one.',
]));
out.push(S('Stage 3R · Perform – listener task (sample)'));
out.push(A('_Better: the pavement; the buses (one an hour → six)._   _Worse: the trees (four → one)._'));
out.push(S('Stage 4 · Your turn (sample)'));
out.push(SAMPLE([
  '_There used to be a market on this square on Tuesdays. There used to be two bakeries and now there is one. There didn\'t use to be a pharmacy. There didn\'t use to be any lights at the crossing, and there used to be an accident there about twice a year._',
  '**A:** What has actually got worse? — **B:** The market. — **A:** Is the market worse, or just different? You buy the same vegetables from a shop forty metres away and you don\'t carry them as far. — **B:** …I am going to have to think about that.',
]));
out.push(S('Stage 4R · Report (sample)'));
out.push(SAMPLE(['Omar\'s corner in Aleppo has a bank where there used to be a cinema, and one tree where there used to be four. But he was honest about the rest: there didn\'t use to be a pavement on that side at all, and there didn\'t use to be a pharmacy, and there used to be one bus an hour instead of six. He says the only thing that has really got worse is the trees, and that he looked at the two photographs for a week before he would say that out loud. I argued with him about the cinema and I lost, because he asked me when I last went to a cinema.']));
out.push(S('Board clinic – typical mistakes'));
out.push(A('✗ There used to be four trees and there used to was a cinema. → ✓ **there used to be** for both.   ✗ There didn\'t used to be a pavement. → ✓ There **didn\'t use to be**.   ✗ There used to be a film on last night. → ✓ There **was** a film on last night.   ✗ It used to have a cinema here. → ✓ **There used to be** a cinema here.'));
out.push(S('Stage 5 · Read'));
out.push(A('**1** A shop, for six years.'));
out.push(A('**2** Because everybody knew the rule — people walked in the road and the cars went round them.'));
out.push(A('**3** Because he expected to write about loss, and when he counted honestly he found that only the trees are worse and everything else is better or the same. He is putting it up anyway, which is the point of the page.'));
out.push(S('Stage 6 · Write with help (sample)'));
out.push(SAMPLE([
  '**AL-JALAA STREET, 2013 AND NOW**',
  'Two photographs from the same doorway, twelve years apart.',
  '**Gone.** There used to be a grocer\'s where the phone shop is now. There used to be three big windows on the corner building; there is one and a wall.',
  '**Arrived.** There didn\'t use to be a crossing at the top of the street at all, and there didn\'t use to be lights. People used to run. There didn\'t use to be bins.',
  '**Honest.** The only thing that is really worse is the corner building. Everything else is better or the same, and the crossing is the reason my mother still walks to the bakery.',
]));
out.push(S('Stage 7 · Write freely (sample, 137 words)'));
out.push(SAMPLE([
  '**THE SCHOOL GATE, 2010 AND NOW** — Hiba',
  'Same gate, same three metres of wall, fifteen years apart.',
  '**Gone.** There used to be a man with a cart selling sweets to the children at half past one; the cart is in the 2010 picture and he is not, because he went to pray and left it standing there. There used to be a wooden door. There used to be forty-five children in a class.',
  '**Arrived.** There didn\'t use to be a library. There is one now, and almost nobody uses it, and the fact that nobody uses it does not stop it being better than no library. There didn\'t use to be a ramp at the gate. There didn\'t use to be thirty in a class — there are now.',
  '**Honest.** I wanted this page to be about the cart. It is really about the ramp, and I did not want it to be.',
]));
out.push(S('Stage 7P · Respond (sample slip)'));
out.push(A('★ _"the cart is in the picture and he is not, because he went to pray" — that is the photograph._   ✓ _Your **Arrived** section is the strongest and it is the shortest. What else arrived?_   ? _Is the library really not used, or do you just not see it?_'));
out.push(S('Stage 7R · Share'));
out.push(A('Counting the class\'s **Gone** and **Arrived** sentences out loud takes two minutes and is the most useful thing in the cycle. Gone is nearly always longer. Then ask the question in the book — _is that the city, or is that us?_ — and do not answer it.'));
out.push(S('Homework (sample – the Arrived paragraph, twice as long)'));
out.push(SAMPLE(['**Arrived.** There didn\'t use to be a library, and there is one now. There didn\'t use to be a ramp at the gate, which means that Rasha\'s brother goes to school in the same building as everybody else and not in a different one on the other side of the city. There didn\'t use to be thirty in a class — there used to be forty-five. There didn\'t use to be a crossing outside, and there didn\'t use to be anybody standing at it at half past one. There didn\'t use to be a telephone in the office that worked, which my mother says is the only change she would call a miracle. And there didn\'t use to be girls in the top class who said out loud that they were going to university.']));

// ===================== 16.4 =====================
out.push(pb());
out.push(h2('16.4  We don\'t do that any more'));
out.push(S('Stage 1 · Get ready'));
out.push(A('**a** Open. The second column always fills faster than the first, which is itself worth pointing out.'));
out.push(A('**b** **1** I **still** walk to work.   **2** I **don\'t** smoke **any more**.   **3** The shop is **still** open.'));
out.push(S('Stage 2 · Listen and read'));
out.push(A('**a** **B** – he still makes the tea the same way… **Careful:** the dialogue says the bread still comes out at the same hour and the family still eats at the same time. The answer is **B** only if your class takes "makes the tea the same way" loosely — the tighter reading is that he still eats at the same time and his brother still comes every Friday. **Accept B and ask for the evidence**, which is the real task.'));
out.push(A('**b** **1** Any two of: people no longer visit without ringing first; nobody writes letters any more; children no longer play in their street.   **2** His brother still comes, still sits in the same chair, and they still argue about the same thing.'));
out.push(S('Language box · Practise'));
out.push(A('**1** I **don\'t smoke any more**.   **2** The shop is **still open**.   **3** People **don\'t visit without ringing any more**.   **4** He **still works** here.   **5** We **no longer write** letters.'));
out.push(NOTE('Item 2 is the position rule: _still_ goes **after** _be_ (_is still open_) but **before** any other verb (_still works_). Students who have learned "still goes before the verb" produce ~~it still is open~~, which is not wrong but is not what anybody says. One line on the board: **after _be_, before everything else.**'));
out.push(S('Stage 3 · Practise (sample – Card A, visiting)'));
out.push(SAMPLE([
  '**A:** What has stopped, with visiting?',
  '**B:** People don\'t come without ringing any more. And nobody stays until midnight any more.',
  '**A:** Why?',
  '**B:** It changed over about ten years. Nobody decided it.',
  '**A:** Is there anything that hasn\'t changed?',
  '**B:** Plenty. We still visit on the first day of Eid, and there is still too much food.',
  '**A:** The same?',
  '**B:** The same table, with different people round it.',
]));
out.push(S('Stage 3R · Perform – listener task (sample)'));
out.push(A('_Stopped: visiting without ringing; staying until midnight._   _Still: the first day of Eid; too much food._ — _still_ before the verb, _any more_ at the end, both times.'));
out.push(S('Stage 4 · Your turn (sample)'));
out.push(SAMPLE([
  '_**No longer:** we don\'t write letters any more; we don\'t sit on the balcony in the evening any more; we don\'t eat together on a Tuesday any more._',
  '_**Still:** we still go to my grandmother\'s on the last Friday of the month; my mother still makes too much food; my uncle still arrives ninety minutes late and still says it was the traffic._',
  '**A:** Who decided about the Tuesday? — **B:** Nobody. My brother\'s shifts changed and it just never came back.',
]));
out.push(S('Stage 4R · Report (sample)'));
out.push(SAMPLE(['In Hiba\'s family nobody writes letters any more, nobody sits on the balcony in the evening any more, and they don\'t eat together on a Tuesday any more because her brother\'s shifts changed and then it just never came back. Nobody decided any of those. What they still do: they still all go to her grandmother\'s on the last Friday of the month, her mother still makes too much food, and her uncle still arrives ninety minutes late and still says the traffic. The one she wants back is the balcony, and she says she is not going to, because the balcony needs four people and she can only produce herself.']));
out.push(S('Board clinic – typical mistakes'));
out.push(A('✗ I work here any more. → ✓ I **don\'t** work here any more.   ✗ I don\'t still work here. → ✓ I don\'t work here **any more**.   ✗ She doesn\'t no longer work here. → ✓ She **no longer works** here.   ✗ It still is open. → ✓ It **is still** open.'));
out.push(S('Stage 5 · Read'));
out.push(A('**1** A death or a problem. It used to be an ordinary Tuesday.'));
out.push(A('**2** Because there is nowhere to put a foot down — the street is full of cars. He says this explicitly: _not because of anything you are thinking_.'));
out.push(A('**3** He still comes every Friday, still sits in the same chair, and they still argue about the same thing they started arguing about in 1979. His brother is still wrong and still thinks Abu Rami is.'));
out.push(S('Stage 6 · Write with help (sample)'));
out.push(SAMPLE([
  '**WHAT WE NO LONGER DO, AND WHAT WE STILL DO** — the office at Medica Trading',
  'Somebody asked me what has changed here in six years, so here it is in two halves.',
  '**Stopped.** We don\'t print anything any more unless somebody signs it. That changed over about two years and the printer decided it, by breaking. Nobody takes a lunch hour any more; people eat at the desk and pretend they are not.',
  '**Still.** We still start at half past eight and we still all arrive at twenty-five past. The tea still comes at eleven and at three. Mr Khaled still asks about the January report four times before anybody has had a chance to finish it.',
  'And we still say "see you tomorrow" on a Thursday, which has never once been true.',
]));
out.push(S('Stage 7 · Write freely (sample, 142 words)'));
out.push(SAMPLE([
  '**WHAT WE NO LONGER DO, AND WHAT WE STILL DO** — our building, fourteen flats',
  '**Stopped.** Nobody leaves the main door open any more. Nobody knows the caretaker\'s name any more, including the caretaker, who is new. We don\'t have the meeting about the stairs any more — we had it every March for nine years and then one March nobody called it and that was that. And children no longer play on the roof, because the door to the roof is locked and nobody will say who locked it.',
  '**Still.** We still all put the bins out on a Sunday night, and we still complain about the one flat that doesn\'t. The woman in flat 3 still brings something to every new family in the week they arrive. The lift still breaks in February. And there is still a chair at the bottom of the stairs that nobody owns and everybody uses.',
  'The chair has been there since before I came. It will be there after I go.',
]));
out.push(S('Stage 7P · Respond (sample slip)'));
out.push(A('★ _"one March nobody called it and that was that" — that is how everything stops._   ✓ _Your two halves are even, which most people\'s are not. Good._   ? _Did anybody decide about the roof? Somebody must have._'));
out.push(S('Stage 7R · Share'));
out.push(A('Reading the **Still** halves alone is the right way round, because the Stopped halves are easy to write and easy to like. The group everybody wants to belong to is the one whose Still half has exact things in it — a chair, a Sunday, a woman in flat 3 — and that is a writing lesson, not a sociology lesson.'));
out.push(S('Homework (sample – the Still half, nothing general)'));
out.push(SAMPLE(['**Still.** The bins go out on a Sunday between eight and nine, and flat 11 still doesn\'t do it. The woman in flat 3 takes a dish to every new family in their first week; she has done it for eleven years and she has never once been thanked in writing. The lift breaks in February — the second week, twice in four years. There is a chair at the bottom of the stairs that belongs to nobody. Umm Fares still shouts the same two names off the balcony at seven in the evening, and both of them are now married and living somewhere else, and she still shouts.']));

// ===================== 16.5 =====================
out.push(pb());
out.push(h2('16.5  It\'s busier than it used to be'));
out.push(S('Stage 1 · Get ready'));
out.push(A('**a** Open. Collect five and vote. The vote matters less than hearing the pattern five times in a row.'));
out.push(A('**b** busy → **busier** · expensive → **more expensive** · good → **better** · far → **further** · easy → **easier** · crowded → **more crowded**'));
out.push(S('Stage 2 · Listen and read'));
out.push(A('**a** **A** – whether life is better. (Omar\'s point is that they are arguing about two different questions.)'));
out.push(A('**b** **1** Everything about information. Her evidence: she fixed a laptop last week using a video made by a man in Indonesia, where ten years ago she would have waited three weeks for a book.   **2** Money. Her evidence is arithmetic, not feeling: her mother ran a house of five people on one salary, and now two of them work and it is tighter.'));
out.push(S('Language box · Practise (samples)'));
out.push(A('**1** The city is **louder than it used to be**.   **2** Food is **more expensive than it used to be**.   **3** The buses are **better than they used to be**.   **4** My English is **worse than it used to be**. _(bad → **worse**, never ~~badder~~)_   **5** Information is **easier to find than it used to be**.   **6** This street is **cleaner than it used to be**.'));
out.push(NOTE('Item 4 catches everybody twice: _bad → worse_, and then the sentence needs _than it used to be_ rather than ~~than before~~. Both are worth one minute each.'));
out.push(S('Stage 3 · Practise (sample – Card A, getting information)'));
out.push(SAMPLE([
  '**A:** Getting information — better or worse than it used to be?',
  '**B:** Much easier than it used to be.',
  '**A:** Why do you say that?',
  '**B:** Because last week I fixed something with a video made by a man on the other side of the world, free, in nine minutes.',
  '**A:** And the other side?',
  '**B:** But it is harder to know what is true than it used to be. That is not a feeling, it is my own week — I believed two things in January that were not so.',
  '**A:** I don\'t agree about the second one, because people believed anything they were told before as well. They just had fewer people telling them.',
]));
out.push(S('Stage 3R · Perform – listener task (sample)'));
out.push(A('_With evidence: "easier — I fixed something with a video, in nine minutes" and "harder to know what is true — I believed two things in January that were not so."_   _Only an opinion: "the buses are worse."_'));
out.push(S('Stage 4 · Your turn (sample)'));
out.push(SAMPLE([
  '_**Better:** my work is more interesting than it used to be — I do three things now and I used to do one. My flat is warmer than it used to be; we put the windows in last year._',
  '_**Worse:** I sleep less than I used to. I go out about a quarter as often as I used to, and I can prove it, because I used to spend money on Thursdays and I don\'t any more._',
  '_**b (where I am part of the reason):** I am a much worse reader than I used to be. Nobody did that to me._',
]));
out.push(S('Stage 4R · Report (sample)'));
out.push(SAMPLE(['Nour says everything about information is easier than it used to be, and her evidence is that she fixed a laptop last week with a video made by a man in Indonesia. Lina says money is harder, and she called that arithmetic rather than a feeling: her mother ran a house of five on one salary, and two of them work now and it is tighter. Rami said the city is cleaner than it was ten years ago and that nobody ever says it, and Lina said she has never heard anybody say it before. The sentence nobody expected was Omar\'s: that he is a much worse reader than he used to be, and that nobody did that to him.']));
out.push(S('Board clinic – typical mistakes'));
out.push(A('✗ more busier → ✓ **busier**.   ✗ more good → ✓ **better**.   ✗ badder → ✓ **worse**.   ✗ busier **that** it used to be → ✓ busier **than** it used to be.'));
out.push(S('Stage 5 · Read'));
out.push(A('**1** Fourteen of the eighteen.'));
out.push(A('**2** Six buses an hour on one route where there used to be one.'));
out.push(A('**3** Because the rest of the page compares the world to the past, which anybody can do; the last section asks where the writer is part of the change, and that is the question the room went quiet for.'));
out.push(S('Stage 6 · Write with help (sample)'));
out.push(SAMPLE([
  '**EASIER OR HARDER?** — the office at Medica Trading',
  'We asked nine people one question: is work easier or harder than it used to be? Seven said both.',
  '**Easier.** Finding a supplier is much easier than it used to be. Rana found three in Türkiye in one morning; in 2017 that took a month and two journeys.',
  '**Harder.** Being paid on time is harder than it used to be. That is not a feeling: in 2019 we waited an average of thirty days and last year it was fifty-two, and the numbers are in the file.',
  '**The thing nobody says.** The office is a kinder place than it used to be. Nobody has shouted in this room for two years.',
  '**The hard question.** I answer four times as many messages as I used to and I think about four times less. Nobody made me do that.',
]));
out.push(S('Stage 7 · Write freely (sample, 151 words)'));
out.push(SAMPLE([
  '**EASIER OR HARDER?** — my own ten years',
  'I asked myself one question and made myself find evidence for every answer, which took longer than writing it.',
  '**Easier.** My English is far better than it used to be: in 2015 I could not read a page without stopping, and I read three pages on the bus this morning and stopped once. And my work is more interesting than it used to be — I do three jobs now where I used to do one.',
  '**Harder.** Money is harder, and it is arithmetic: the same shopping cost a quarter of a day\'s work and now it costs most of one. Sleeping is harder. I used to sleep from eleven; I now go to bed at eleven, which is a different thing.',
  '**The thing nobody says.** I am much less afraid of strangers than I used to be. Six years of a job where I have to telephone people did that.',
  '**The hard question.** I am a worse friend than I used to be. I answer when people write and I never write first, and I have been telling myself for three years that I am busy. Nobody did that to me.',
]));
out.push(S('Stage 7P · Respond (sample slip)'));
out.push(A('★ _"I go to bed at eleven, which is a different thing." I know exactly what that sentence means._   ✓ _"My work is more interesting" — three jobs instead of one is a number, but is it evidence of interesting?_   ? _Your hard question: who would you write to first, if you wrote to one person tonight?_'));
out.push(S('Stage 7R · Share'));
out.push(A('Read the hard-question sentences anonymously, slowly, and **leave the silence**. Then ask how many are the same sentence. In most classes three or four students have written some version of _I read less_ or _I am a worse friend_, and discovering that it is shared is worth more than any correction you could make.'));
out.push(S('Homework (sample)'));
out.push(SAMPLE(['**I am a worse reader than I used to be.** I used to read a book a fortnight, and I used to carry one everywhere, and I used to finish them even when they were bad. Now I read four pages at night and lose them. I have bought eleven books this year and finished two. Nobody did this to me; I did it a minute at a time, and every minute looked free. The first small thing: I am going to put the telephone in the kitchen at nine o\'clock and read in a room it is not in. Not for ever. For a fortnight, to find out whether the problem is me or the room.']));

// ===================== 16.6 =====================
out.push(pb());
out.push(h2('16.6  She says it was better then'));
out.push(S('Stage 1 · Get ready'));
out.push(A('**a** Open. Insist on the two steps — the person\'s own words first, then the report — because the report is only interesting next to the original.'));
out.push(A('**b** **1** _He says (that) he **used to walk** to school._   **2** _She says (that) **there used to be** nine bookshops._   **3** _He said (that) **nobody writes** letters **any more**._'));
out.push(NOTE('The point of all three is that **nothing changes** except the reporting verb. At A2 we do not backshift. A student who writes _He says that he had walked to school_ has invented a tense nobody asked for, and the fix is to show them the original sentence next to the report.'));
out.push(S('Stage 2 · Listen and read'));
out.push(A('**a** **B** – the older people they interviewed.'));
out.push(A('**b** **1** That the street used to be full of people walking slowly and looking in windows, and that some of them used to buy a book.   **2** Any of it. She says she will not tell them it was better, because she remembers carrying water up four floors and a child ill at night in a building with no telephone.'));
out.push(S('Language box · Practise'));
out.push(A('**1** He **says** (that) he **used to walk** to school.   **2** She **says** (that) **there used to be** nine bookshops.   **3** He **said** (that) **nobody decided** it.   **4** She **said** (that) she **does not miss** any of it.   **5** She **says** (that) the bread **was** better.'));
out.push(S('Stage 3 · Practise (sample – Card A)'));
out.push(SAMPLE([
  '**A:** Mrs Mona said: "There used to be nine bookshops in this street."',
  '**B:** So Mrs Mona says that there used to be nine bookshops in her street.',
  '**A:** Exactly.',
  '**B:** And does she also say that people used to read more?',
  '**A:** She says people buy the same number of books. They just don\'t come in any more.',
  '**B:** Then she is reliable, because she has refused the easy answer twice.',
]));
out.push(S('Stage 3R · Perform – listener task (sample)'));
out.push(A('_"She says that there used to be nine bookshops in her street." · "She says people buy the same number of books but no longer come in."_ — ordinary word order after _that_, and _used to_ unchanged.'));
out.push(S('Stage 4 · Your turn (sample)'));
out.push(SAMPLE([
  '_My mother says that there used to be twenty-two children in our building and that she knew all their mothers by name. She says she now knows two. She says people used to visit without ringing, constantly. She said her mother used to cook as if four extra people were coming every day, and that four extra people usually came. Her words: "The building is quieter and I am not sure that is the same as better."_',
  '**b** _She also says that children were better behaved then, and I don\'t believe that one. She has told me three stories about my uncle that disprove it, and she told them to me laughing._',
]));
out.push(S('Stage 4R · Report (sample)'));
out.push(SAMPLE(['Nour interviewed her grandmother and brought in the sentence nobody expected. She says her grandmother does not miss any of it. She says that everybody her grandmother\'s age tells you it was better and that her grandmother will not, because she remembers carrying water up four floors and she remembers what it is like when a child is ill at night and there is no telephone in the building. Her exact words were: "They are remembering being young. I was young too, and I remember the stairs." And then Nour said that her grandmother also says the bread was better, so she is not completely reliable, and Ms Huda said that keeping both of those is what a careful report is.']));
out.push(S('Board clinic – typical mistakes'));
out.push(A('✗ She says me that… → ✓ She **says** that… / She **tells me** that…   ✗ She said that was it better. → ✓ She said that **it was** better.   ✗ She says that there had used to be nine. → ✓ …that **there used to be** nine.   ✗ He said me he doesn\'t miss it. → ✓ He **told me** he doesn\'t miss it.'));
out.push(S('Stage 5 · Read'));
out.push(A('**1** Come in without a reason. (They still buy the same number of books.)'));
out.push(A('**2** Carrying water up four floors, and a child ill at night in a building with no telephone.'));
out.push(A('**3** Because a careful report keeps the parts that contradict each other. She does not miss any of it **and** the bread was better — tidying either one away would make the report the writer\'s opinion instead of hers.'));
out.push(S('Stage 6 · Write with help (sample)'));
out.push(SAMPLE([
  '**WHAT THEY TOLD US** — two interviews, Room 12',
  '**Mr Nabil, 64, Mezzeh, retired teacher.** He says there used to be forty-five children in a class and that there are now thirty. He says there didn\'t use to be a library, but that the one they have now is hardly used.',
  '**Umm Fares, 76, Jaramana.** She said she does not want to be asked what it was like. Her words: "Ask me what I had to do before breakfast. Then you will know what it was like."',
  'She also says that people were kinder then, so, like most of us, she keeps two opinions that do not fit together.',
]));
out.push(S('Stage 7 · Write freely (sample, 156 words)'));
out.push(SAMPLE([
  '**WHAT THEY TOLD US** — three interviews, Room 12',
  '**Mrs Mona, bookshop, Shaalan.** She says there used to be nine bookshops in four hundred metres and that nobody noticed any of them closing. She says people still buy the same number of books but that they no longer come in without a reason, and that a bookshop lives on the other kind of customer.',
  '**Abu Rami, 71, Homs.** He says the thing that stopped was visiting without ringing first, that nobody decided it, and that it took about ten years. He says he and his brother still argue every Friday about something they started in 1979, and that his brother is still wrong.',
  '**Umm Kinan, 83, Damascus.** She said she does not miss any of it. She said everybody her age tells you it was better and that she will not, because she remembers carrying water up four floors and a child ill at night in a building with no telephone. Her words: "They are remembering being young. I was young too, and I remember the stairs."',
  'She also says the bread was better. Both of those are in this report on purpose.',
]));
out.push(S('Stage 7P · Respond (sample slip)'));
out.push(A('★ _You got me right — you kept the bread._   ✓ _You made Abu Rami tidier than he is; he does not finish his sentences and yours all finish._   ? _Why did you leave out what I said about my sister?_'));
out.push(S('Stage 7R · Share'));
out.push(A('Reading the whole wall end to end is the close of the unit and it should not be hurried — give it six minutes and ask for the one sentence at the end. The sentences students produce here are consistently the best writing in Book 2 so far, and several of them are worth keeping for Unit 24.'));
out.push(S('Homework (sample)'));
out.push(SAMPLE(['**My grandfather, 88, Latakia.** I asked him what has stopped and what still happens. He says the fishing boats used to go out at four and that there used to be more of them than anybody could count. He says nobody mends a net by hand any more, and that he was the last person in our family who could. He says he still walks to the same place on the sea wall every morning, still at six, and that he no longer goes on the sand because of his knee. His words: "The sea has not changed at all, and everybody tells me it has."']));

